{
  "estrategia_elegida": "B",
  "resumen": "Se elige la estrategia B (Protección de ventanas críticas) porque maximiza la entrega de pedidos urgentes (4/8) y mantiene una puntualidad razonable (4/20) bajo condiciones normales, y aunque pierde 5 puntos bajo estrés, sigue cumpliendo mejor con el margen crítico del P20 en Callao. Las demás estrategias entregan menos urgentes o pierden puntualidad bajo estrés. Se requiere autorización para gestionar la falta de capacidad y frío mediante segunda vuelta o vehículo adicional.",
  "por_que": [
    "Mayor número de urgentes atendidos (4/8) alineado con peso 20% del objetivo.",
    "Puntualidad aceptable (4/20) y no degradada a menos de 15 bajo estrés.",
    "Resistencia al estrés superior a C (caída 5 pts vs 5 pts pero con peor puntualidad).",
    "Cumple mejor el margen de 28 min del P20 urgente."
  ],
  "criterios_que_pesaron": [
    {
      "criterio": "Urgentes entregados",
      "importancia": "alta",
      "evidencia": "B entrega 4 de 8 urgentes vs A 1/8, C 2/8, H 2/8"
    },
    {
      "criterio": "Puntualidad",
      "importancia": "media",
      "evidencia": "B 4/20 a tiempo (15 bajo estrés) vs A 6/20 (30 bajo estrés) pero A solo 1 urgente"
    },
    {
      "criterio": "Caída bajo estrés",
      "importancia": "media",
      "evidencia": "B pierde 5 puntos de puntaje, C también pierde 5 pero con peor puntualidad"
    },
    {
      "criterio": "Cumplimiento de margen urgente P20",
      "importancia": "alta",
      "evidencia": "B coloca P20 al inicio de la secuencia de F1, garantizando salida directa"
    }
  ],
  "desviacion_del_ranking": "ninguna",
  "trade_offs": [
    "Se sacrifica algo de puntualidad (4/20) frente a la estrategia A que tiene 6/20 pero casi ninguna entrega urgente.",
    "Mayor consumo de km y costo (557.6 S/ vs 469.3 S/ de A) debido a rutas menos óptimas."
  ],
  "riesgos": [
    {
      "riesgo": "Capacidad insuficiente por vuelta (1512 kg > 630 kg)",
      "mitigacion": "Programar segunda vuelta para cada vehículo y validar tiempos de carga antes de salida."
    },
    {
      "riesgo": "Refrigeración insuficiente (1127 kg > 630 kg)",
      "mitigacion": "Asignar carga refrigerada en dos turnos o contratar unidad con cámara fría adicional."
    },
    {
      "riesgo": "Posible retraso del P20 si la primera ventana se congestiona",
      "mitigacion": "Monitorear tráfico en tiempo real y, de ser necesario, reordenar entregas urgentes con la moto M1."
    }
  ],
